void main() {
  // Бүтін сандар (int)
  int age = 25;
  int temperature = -10;

  // Бөлшек сандар (double)
  double price = 99.99;
  double pi = 3.14159;

  // Арифметикалық операциялар
  int sum = 10 + 5;        // 15
  int diff = 10 - 5;       // 5
  int product = 10 * 5;    // 50
  double quotient = 10 / 3; // 3.333...
  int intDiv = 10 ~/ 3;    // 3
  int remainder = 10 % 3;   // 1

  print('Сома: $sum');
  print('Бөлу: $quotient');
  print('Бүтін бөлу: $intDiv');

  // Пайдалы әдістер
  double num = -5.7;
  print('Модуль: ${num.abs()}');      // 5.7
  print('Дөңгелектеу: ${num.round()}'); // -6
  print('Жоғары: ${num.ceil()}');      // -5
  print('Төмен: ${num.floor()}');      // -6
}

void main() {
  // Жолдарды жасау
  String name = 'Асет';
  String city = "Алматы";

  // Интерполяция
  int age = 20;
  print('Менің атым $name');
  print('Маған ${age + 1} жас');

  // Қасиеттер мен әдістер
  String text = '  Сәлем, Әлем!  ';
  print('Ұзындығы: ${text.length}');  // 16
  print('Үлкен әріп: ${text.toUpperCase()}');
  print('Кіші әріп: ${text.toLowerCase()}');
  print('Бос орынсыз: "${text.trim()}"');

  // Тексерулер
  print(text.contains('Әлем'));     // true
  print(text.startsWith('Сәл'));   // false (бос орындар бар)
  print(text.trim().startsWith('Сәл')); // true

  // Ішкі жолдармен жұмыс
  String greeting = 'Сәлем, әлем!';
  print(greeting.substring(0, 5));  // Сәлем
  print(greeting.replaceAll('әлем', 'Dart')); // Сәлем, Dart!
}

void main() {
  // Логикалық мәндер
  bool isStudent = true;
  bool hasLicense = false;

  // Салыстыру операторлары
  int age = 20;
  bool isAdult = age >= 18;        // true
  bool isTeenager = age >= 13 && age <= 19; // false

  print('Кәмелетке толған: $isAdult');
  print('Жасөспірім: $isTeenager');

  // Логикалық операторлар
  bool canDrive = age >= 18 && hasLicense;
  bool needsPermission = age < 18 || !hasLicense;

  print('Көлік жүргізе алады: $canDrive');
  print('Рұқсат қажет: $needsPermission');

  // Инверсия
  bool isNotStudent = !isStudent;  // false
  print('Студент емес: $isNotStudent');

  // Күрделі шарттар
  int score = 85;
  bool passedExam = score >= 60 && score <= 100;
  bool excellentScore = score >= 90;

  print('Емтихан тапсырды: $passedExam');
  print('Өте жақсы нәтиже: $excellentScore');
}

void main() {
  // Тізімдерді жасау
  var fruits = ['алма', 'банан', 'апельсин'];
  print('Жемістер: $fruits');

  // Индекс бойынша қол жеткізу
  print('Бірінші жеміс: ${fruits[0]}');
  print('Соңғы: ${fruits[fruits.length - 1]}');

  // Элементті өзгерту
  fruits[1] = 'манго';
  print('Өзгерткеннен кейін: $fruits');

  // Элементтерді қосу
  fruits.add('жүзім');
  fruits.insert(0, 'киви');
  print('Қосқаннан кейін: $fruits');

  // Жою
  fruits.remove('манго');
  fruits.removeAt(0);
  print('Жойғаннан кейін: $fruits');

  // Тексерулер
  print('Тізім ұзындығы: ${fruits.length}');
  print('Алма бар: ${fruits.contains("алма")}');
  print('Бос: ${fruits.isEmpty}');

  // Пайдалы операциялар
  var numbers = [3, 1, 4, 1, 5];
  print('Бірінші: ${numbers.first}');
  print('Соңғы: ${numbers.last}');
  print('Аударылған: ${numbers.reversed.toList()}');
}

void main() {
  // Жиындарды жасау
  var numbers = {1, 2, 3, 2, 1}; // Қайталанулар жойылады
  print('Сандар: $numbers'); // {1, 2, 3}

  var fruits = {'алма', 'банан'};

  // Қосу
  fruits.add('апельсин');
  fruits.add('банан'); // Қосылмайды (бар)
  print('Жемістер: $fruits');

  // Тексерулер
  print('Алма бар: ${fruits.contains("алма")}');
  print('Саны: ${fruits.length}');

  // Жиындар үстіндегі операциялар
  var set1 = {1, 2, 3, 4};
  var set2 = {3, 4, 5, 6};

  print('Бірігу: ${set1.union(set2)}');
  // {1, 2, 3, 4, 5, 6}

  print('Қиылысу: ${set1.intersection(set2)}');
  // {3, 4}

  print('Айырмашылық: ${set1.difference(set2)}');
  // {1, 2}

  // List -> Set түрлендіру (қайталануларды жою)
  var listWithDuplicates = [1, 2, 2, 3, 3, 3];
  var uniqueNumbers = listWithDuplicates.toSet();
  print('Бірегейлер: $uniqueNumbers'); // {1, 2, 3}
}

void main() {
  // Сөздікті жасау
  var student = {
    'name': 'Асет',
    'age': 20,
    'course': 2,
    'university': 'ҚазҰУ'
  };

  // Мәндерге қол жеткізу
  print('Аты: ${student['name']}');
  print('Жасы: ${student['age']}');

  // Қосу және өзгерту
  student['gpa'] = 3.8;
  student['age'] = 21;
  print('Жаңартылған: $student');

  // Жою
  student.remove('course');
  print('Жойғаннан кейін: $student');

  // Кілттер мен мәндермен жұмыс
  print('Кілттер: ${student.keys}');
  print('Мәндер: ${student.values}');

  // Тексерулер
  print('name кілті бар: ${student.containsKey("name")}');
  print('20 мәні бар: ${student.containsValue(20)}');
  print('Өрістер саны: ${student.length}');

  // Сөздік бойынша итерация
  student.forEach((key, value) {
    print('$key: $value');
  });

  // Пәндер бойынша бағалар
  Map<String, int> grades = {
    'математика': 95,
    'физика': 88,
    'программалау': 92
  };
  print('\nБағалар: $grades');
}

