void main() {
  // Non-nullable - null бола алмайды
  String name = 'Асет';
  // name = null; // ❌ Компиляция қатесі!
  print('Аты: $name');

  // Nullable - null бола алады
  String? nickname = null;
  print('Nickname: $nickname');

  // Safe call operator ?.
  String? city;
  print('Қала ұзындығы: ${city?.length}'); // null (қате емес!)

  city = 'Алматы';
  print('Қала ұзындығы: ${city?.length}'); // 6

  // Null-coalescing operator ??
  String? username;
  String displayName = username ?? 'Қонақ';
  print('Көрсетілетін аты: $displayName'); // Қонақ

  username = 'aset_dev';
  displayName = username ?? 'Қонақ';
  print('Көрсетілетін аты: $displayName'); // aset_dev

  // Null-aware assignment ??=
  String? greeting;
  greeting ??= 'Сәлем!';
  print('Сәлемдесу 1: $greeting'); // Сәлем!

  greeting ??= 'Қайырлы күн!';
  print('Сәлемдесу 2: $greeting'); // Сәлем! (өзгерген жоқ)

  // Not-null assertion !
  String? email = 'test@example.com';
  int emailLength = email!.length; // null емес екеніне сенімдіміз
  print('Email ұзындығы: $emailLength');

  // Late айнымалылар - кейін инициализациялау
  late String lateVar;
  lateVar = 'Кейін инициализацияланды';
  print('Late айнымалы: $lateVar');
}

void main() {
  // var - инициализация кезінде түр бекітіледі
  var varExample = 10; // int
  print('var мысалы: $varExample');
  // varExample = 'text'; // ❌ Компиляция қатесі!

  // dynamic - түр өзгере алады
  dynamic dynExample = 10;
  print('dynamic int ретінде: $dynExample');

  dynExample = 'Енді жол!';
  print('dynamic String ретінде: $dynExample');

  dynExample = true;
  print('dynamic bool ретінде: $dynExample');

  dynExample = [1, 2, 3];
  print('dynamic List ретінде: $dynExample');

  // Object - базалық түр
  Object objExample = 10;
  print('Object мысалы: $objExample');

  objExample = 'Түрді өзгертуге де болады';
  print('Object String ретінде: $objExample');

  // Бірақ түрге келтірусіз әдістерді шақыруға болмайды
  // int length = objExample.length; // ❌ Қате!

  // is арқылы түрді тексеру
  dynamic value = 'Сәлем, Dart!';

  if (value is String) {
    print('Бұл жол, ұзындығы: ${value.length}');
  } else if (value is int) {
    print('Бұл сан');
  }

  // as арқылы түрге ашық келтіру
  dynamic numValue = 42;
  int number = numValue as int;
  print('int-ке келтірілді: $number');

  // Практикалық мысал - JSON
  dynamic jsonData = {
    'name': 'Асет',
    'age': 20,
    'isStudent': true,
    'scores': [95, 88, 92]
  };

  print('\n=== JSON Деректері ===');
  print('Аты: ${jsonData['name']}');
  print('Жасы: ${jsonData['age']}');
  print('Студент: ${jsonData['isStudent']}');
  print('Бағалар: ${jsonData['scores']}');

  // dynamic-пен қауіпсіз жұмыс
  dynamic unsafeValue = 'test';

  if (unsafeValue is int) {
    int safeValue = unsafeValue;
    print('Қауіпсіз int мәні: $safeValue');
  } else {
    print('Мән int емес, ${unsafeValue.runtimeType}');
  }
}
